import{_ as t,o as l,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Month 2021: CephFS + fscrypt: filename and content encryption","description":"","frontmatter":{"title":"Ceph Month 2021: CephFS + fscrypt: filename and content encryption","date":"2021-06-24T00:00:00.000Z","updated":"2021-06-25T00:00:00.000Z","tags":["CephFS","fscrypt","transparent encryption","encryption","Ceph"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_CephFS_+_fscrypt_-_filename_and_content_encryption.md","filePath":"posts/2021/Ceph_Month_2021_-_CephFS_+_fscrypt_-_filename_and_content_encryption.md","lastUpdated":1780459816000}'),n={name:"posts/2021/Ceph_Month_2021_-_CephFS_+_fscrypt_-_filename_and_content_encryption.md"};function r(o,e,s,p,h,c){return l(),a("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-cephfs与fscrypt透明加密支持" tabindex="-1">会议主题：CephFS与fscrypt透明加密支持 <a class="header-anchor" href="#会议主题-cephfs与fscrypt透明加密支持" aria-label="Permalink to &quot;会议主题：CephFS与fscrypt透明加密支持&quot;">​</a></h4><h4 id="主讲人-jeff" tabindex="-1">主讲人：Jeff <a class="header-anchor" href="#主讲人-jeff" aria-label="Permalink to &quot;主讲人：Jeff&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>项目背景与目标</strong>：</p><ul><li>Jeff自一年前开始开发fscrypt项目，旨在为Ceph文件系统提供透明加密支持。</li><li>fscrypt是一个内核库，允许文件系统调用以实现文件名、文件内容和符号链接目标的透明加密。</li></ul></li><li><p><strong>技术细节</strong>：</p><ul><li>fscrypt在文件系统级别操作，不需要密钥来挂载文件系统，但需要密钥来访问和操作加密的目录树。</li><li>目前支持fscrypt的文件系统包括ext4、f2fs和ubifs，Jeff正在努力使其适用于网络文件系统。</li></ul></li><li><p><strong>加密机制</strong>：</p><ul><li>每个加密的目录树有一个主密钥，每个加密的inode有一个关联的加密上下文。</li><li><code>fscrypt</code>使用密钥派生函数生成每个inode的密钥，确保即使丢失密钥也能清理目录并回收空间。</li></ul></li><li><p><strong>用户工具与工作流程</strong>：</p><ul><li>提供了一个用Golang编写的用户空间工具，用于生成和管理主密钥。</li><li>工作流程包括初始化、文件系统设置、加密空目录以及锁定和解锁目录。</li></ul></li><li><p><strong>inode数据存储</strong>：</p><ul><li>每个inode关联一个40字节的blob，包含加密模式、主密钥ID和随机数据（nonce）等信息。</li><li>使用base64编码来确保文件名的合法性，并在必要时对文件名进行截断和哈希处理。</li></ul></li><li><p><strong>MDS（元数据服务器）支持</strong>：</p><ul><li>引入了一个新的fs crypt auth属性，挂载在inode上，MDS将其视为不透明的blob。</li><li>增加了新的pert entry alternate name字段，用于存储完整的加密文件名。</li></ul></li><li><p><strong>内容加密挑战</strong>：</p><ul><li>内容加密仍在进行中，涉及AES加密和处理块数据的问题。</li><li>需要处理截断操作，确保不会破坏加密块的完整性。</li></ul></li><li><p><strong>演示与反馈</strong>：</p><ul><li>Jeff展示了如何在Ceph集群中使用<code>fscrypt</code>加密目录，并演示了加密前后的文件名变化。</li><li>讨论了将此功能扩展到其他文件系统（如SMB和NFS）的可能性。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>继续完善内容加密部分，解决截断操作和数据路径的问题。</li><li>探索将加密功能集成到新的库模块netfs中，以支持更广泛的网络文件系统。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续推进<code>fscrypt</code>在Ceph中的集成，特别是内容加密和数据路径的优化。</li><li>考虑将此功能扩展到其他文件系统，如SMB和NFS。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>Jeff将继续完善<code>fscrypt</code>的实现，并寻求社区的帮助和支持。</li><li>社区成员可以关注并参与相关的代码审查和测试工作。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>Jeff感谢大家的参与和反馈，并期待在未来的版本中看到这一功能的完整实现。</li></ul>',14)])])}const _=t(n,[["render",r]]);export{d as __pageData,_ as default};
